def transform(grid):
    h, w = len(grid), len(grid[0])
    crosses = []
    for r in range(h):
        for c in range(w):
            if (r > 0 and r + 1 < h and c > 0 and c + 1 < w and
                grid[r-1][c] == grid[r+1][c] ==
                grid[r][c-1] == grid[r][c+1] == 3):
                crosses.append((r, c, grid[r][c]))

    hlines = [[0] * w for _ in range(h)]
    vlines = [[0] * w for _ in range(h)]
    arms = {}
    for r, c, color in crosses:
        for p in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            arms.setdefault(p, set()).add((r, c))

    for r, c, color in crosses:
        if color in (0, 3):
            continue

        for dr, dc, layer in ((0, -1, hlines), (0, 1, hlines),
                              (-1, 0, vlines), (1, 0, vlines)):
            y, x = r + dr, c + dc
            while 0 <= y < h and 0 <= x < w:
                if grid[y][x] == 3 and (r, c) not in arms.get((y, x), set()):
                    break
                if grid[y][x] == 0:
                    layer[y][x] = color
                y += dr
                x += dc

    null_rows = {r for r, c, color in crosses if color == 0}
    null_cols = {c for r, c, color in crosses if color == 0}

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            # Blank crosses erase horizontal rays along their row or column.
            horizontal = hlines[r][c]
            if r in null_rows or c in null_cols:
                horizontal = 0
            # Vertical rays survive intersections with blank horizontal rows,
            # but are erased by blank vertical columns.
            vertical = 0 if c in null_cols else vlines[r][c]
            out[r][c] = vertical if vertical else horizontal
    return out
